using System.Collections.Generic;using System.Linq;using Horizon.Game.GengDi.Data.Storage;using Horizon.Game.GengDi.Models;using LiteDB;namespace Horizon.Game.GengDi.Data.Repositories{    public class ActivityRepository    {        private readonly LiteDatabase _database;
        private readonly ILiteCollection<Activity> _collection;        public ActivityRepository()        {            _database = DatabaseManager.Database;
            _collection = _database.GetCollection<Activity>();        }        public void Add(Activity activity)        {            _collection.Insert(activity);        }        public void Update(Activity activity)        {            _collection.Update(activity);        }        public void Delete(string id)        {            _collection.Delete(id);        }        public Activity GetById(string id)        {            return _collection.FindById(id);        }        public List<Activity> GetAll()        {            return _collection.FindAll().OrderByDescending(a => a.StartDate).ToList();        }        public List<Activity> GetActiveActivities()        {            var now = DateTime.Now;            return _collection.Find(a => a.StartDate <= now && a.EndDate >= now).OrderByDescending(a => a.StartDate).ToList();        }        public List<Activity> GetActivitiesByType(string type)        {            return _collection.Find(a => a.Type == type).OrderByDescending(a => a.StartDate).ToList();        }    }} 